import fs from 'node:fs';
import { styleText } from 'node:util';

import {
  dynamicImport,
  isObject,
  isString,
  type PackageJson,
  resolveInstalledVersions,
} from '@orval/core';
import yaml from 'js-yaml';
import JSON5 from 'json5';

import { logger } from '../logger';
import { findUp, findUpMultiple } from './find-up';
import { normalizePath } from './options';

type CatalogData = Pick<PackageJson, 'catalog' | 'catalogs'>;

export const loadPackageJson = async (
  packageJson?: string,
  workspace = process.cwd(),
): Promise<PackageJson | undefined> => {
  if (!packageJson) {
    const pkgPath = findUp('package.json', workspace);
    if (pkgPath) {
      const pkg = await dynamicImport<unknown>(pkgPath, workspace);

      if (isPackageJson(pkg)) {
        return resolveAndAttachVersions(
          await maybeReplaceCatalog(pkg, workspace),
          workspace,
          pkgPath,
        );
      } else {
        throw new Error('Invalid package.json file');
      }
    }
    return;
  }

  const normalizedPath = normalizePath(packageJson, workspace);
  if (fs.existsSync(normalizedPath)) {
    let pkg: unknown;
    try {
      pkg = JSON5.parse(
        await fs.promises.readFile(normalizedPath, 'utf8'),
      ) as unknown;
    } catch (error) {
      throw new Error(
        `Oups... 🍺. Path: ${normalizedPath} => ${String(error)}`,
        { cause: error },
      );
    }

    if (isPackageJson(pkg)) {
      return resolveAndAttachVersions(
        await maybeReplaceCatalog(pkg, workspace),
        workspace,
        normalizedPath,
      );
    } else {
      throw new Error(`Invalid package.json file: ${normalizedPath}`);
    }
  }
  return;
};

const isPackageJson = (obj: unknown): obj is PackageJson => isObject(obj);

const resolvedCache = new Map<string, Record<string, string>>();

const resolveAndAttachVersions = (
  pkg: PackageJson,
  workspace: string,
  cacheKey: string,
): PackageJson => {
  const cached = resolvedCache.get(cacheKey);
  if (cached) {
    pkg.resolvedVersions = cached;
    return pkg;
  }

  const resolved = resolveInstalledVersions(pkg, workspace);
  if (Object.keys(resolved).length > 0) {
    pkg.resolvedVersions = resolved;
    resolvedCache.set(cacheKey, resolved);
    for (const [name, version] of Object.entries(resolved)) {
      logger.verbose(
        styleText(
          'dim',
          `Detected ${styleText('white', name)} v${styleText('white', version)}`,
        ),
      );
    }
  }
  return pkg;
};

const hasCatalogReferences = (pkg: PackageJson): boolean => {
  return [
    ...Object.entries(pkg.dependencies ?? {}),
    ...Object.entries(pkg.devDependencies ?? {}),
    ...Object.entries(pkg.peerDependencies ?? {}),
  ].some(([, value]) => isString(value) && value.startsWith('catalog:'));
};

const pickCatalog = (
  data: Record<string, unknown> | undefined,
): CatalogData | undefined =>
  data?.catalog || data?.catalogs
    ? {
        catalog: data.catalog as CatalogData['catalog'],
        catalogs: data.catalogs as CatalogData['catalogs'],
      }
    : undefined;

/** The catalog of the nearest `fileName` (pnpm-workspace.yaml, .yarnrc.yml). */
const loadYamlCatalog = async (
  fileName: string,
  workspace: string,
): Promise<CatalogData | undefined> => {
  const filePath = findUp(fileName, workspace);
  if (!filePath) return undefined;
  try {
    const file = await fs.promises.readFile(filePath, 'utf8');
    return pickCatalog(yaml.load(file) as Record<string, unknown> | undefined);
  } catch {
    return undefined;
  }
};

const loadPackageJsonCatalog = async (
  workspace: string,
): Promise<CatalogData | undefined> => {
  for (const filePath of findUpMultiple('package.json', workspace)) {
    try {
      // fs-extra's readJson stripped a leading BOM; JSON.parse rejects it.
      const catalog = pickCatalog(
        JSON.parse(
          (await fs.promises.readFile(filePath, 'utf8')).replace(/^\uFEFF/, ''),
        ) as Record<string, unknown>,
      );
      if (catalog) return catalog;
    } catch {
      // Continue to next file
    }
  }
  return undefined;
};

const maybeReplaceCatalog = async (
  pkg: PackageJson,
  workspace: string,
): Promise<PackageJson> => {
  if (!hasCatalogReferences(pkg)) {
    return pkg;
  }

  const catalogData =
    (await loadYamlCatalog('pnpm-workspace.yaml', workspace)) ??
    (await loadPackageJsonCatalog(workspace)) ??
    (await loadYamlCatalog('.yarnrc.yml', workspace));

  if (!catalogData) {
    logger.warn(
      'package.json contains catalog: references, but no catalog source was found (checked: pnpm-workspace.yaml, package.json, .yarnrc.yml).',
    );
    return pkg;
  }

  performSubstitution(pkg.dependencies, catalogData);
  performSubstitution(pkg.devDependencies, catalogData);
  performSubstitution(pkg.peerDependencies, catalogData);

  return pkg;
};

const performSubstitution = (
  dependencies: Record<string, string> | undefined,
  catalogData: CatalogData,
) => {
  if (!dependencies) return;
  for (const [packageName, version] of Object.entries(dependencies)) {
    if (version === 'catalog:' || version === 'catalog:default') {
      if (!catalogData.catalog) {
        logger.warn(
          `catalog: substitution for the package '${packageName}' failed as there is no default catalog.`,
        );
        continue;
      }
      const sub = catalogData.catalog[packageName];
      if (!sub) {
        logger.warn(
          `catalog: substitution for the package '${packageName}' failed as there is no matching package in the default catalog.`,
        );
        continue;
      }
      dependencies[packageName] = sub;
    } else if (version.startsWith('catalog:')) {
      const catalogName = version.slice('catalog:'.length);
      const catalog = catalogData.catalogs?.[catalogName];
      if (!catalog) {
        logger.warn(
          `'${version}' substitution for the package '${packageName}' failed as there is no matching catalog named '${catalogName}'. (available named catalogs are: ${Object.keys(catalogData.catalogs ?? {}).join(', ')})`,
        );
        continue;
      }
      const sub = catalog[packageName];
      if (!sub) {
        logger.warn(
          `'${version}' substitution for the package '${packageName}' failed as there is no package in the catalog named '${catalogName}'. (packages in the catalog are: ${Object.keys(catalog).join(', ')})`,
        );
        continue;
      }
      dependencies[packageName] = sub;
    }
  }
};
